import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

type Preset = {
  id: string;
  label: string;
  offsetDays: number;
};

const PRESETS: Preset[] = [
  { id: 'today', label: 'Сегодня', offsetDays: 0 },
  { id: 'yesterday', label: 'Вчера', offsetDays: -1 },
  { id: 'week-ago', label: 'Неделя назад', offsetDays: -7 },
];

function shiftDays(offsetDays: number): Date {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  date.setDate(date.getDate() + offsetDays);
  return date;
}

function isSameDay(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
}: ReportDatePickerProps) {
  const [internalValue, setInternalValue] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internalValue;

  const select = (next: Date | null) => {
    if (value === undefined) {
      setInternalValue(next);
    }
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {PRESETS.map((preset) => {
          const presetDate = shiftDays(preset.offsetDays);
          const active = isSameDay(selected, presetDate);
          return (
            <JxChip
              key={preset.id}
              active={active}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => select(presetDate)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(presetDate);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar
        locale="ru-RU"
        value={selected}
        onValueChange={select}
        aria-label="Дата отчёта"
      />
    </div>
  );
}

